#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to;
    int next;
} Edge;

typedef struct {
    int *head;
    Edge *edges;
    int edge_cnt;
    int n;
} Graph;

static void init_graph(Graph *g, int n) {
    g->n = n;
    g->edge_cnt = 0;
    g->head = (int *)malloc((n + 1) * sizeof(int));
    g->edges = (Edge *)malloc((2 * n + 2) * sizeof(Edge));
    for (int i = 0; i <= n; i++) {
        g->head[i] = -1;
    }
}

static void add_edge(Graph *g, int u, int v) {
    g->edges[g->edge_cnt].to = v;
    g->edges[g->edge_cnt].next = g->head[u];
    g->head[u] = g->edge_cnt++;

    g->edges[g->edge_cnt].to = u;
    g->edges[g->edge_cnt].next = g->head[v];
    g->head[v] = g->edge_cnt++;
}

static void free_graph(Graph *g) {
    free(g->head);
    free(g->edges);
}

static int bfs_farthest(const Graph *g, int start, int *dist, int *parent) {
    for (int i = 1; i <= g->n; i++) {
        dist[i] = -1;
        if (parent) parent[i] = 0;
    }

    int *queue = (int *)malloc((g->n + 1) * sizeof(int));
    int head = 0, tail = 0;

    dist[start] = 0;
    queue[tail++] = start;

    int farthest = start;

    while (head < tail) {
        int u = queue[head++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = g->head[u]; e != -1; e = g->edges[e].next) {
            int v = g->edges[e].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent) parent[v] = u;
                queue[tail++] = v;
            }
        }
    }

    free(queue);
    return farthest;
}

static int find_center(const Graph *g) {
    int *dist = (int *)malloc((g->n + 1) * sizeof(int));
    int *parent = (int *)malloc((g->n + 1) * sizeof(int));

    int u = bfs_farthest(g, 1, dist, NULL);
    int v = bfs_farthest(g, u, dist, parent);

    int path_len = dist[v];
    int steps = path_len / 2;

    int curr = v;
    for (int i = 0; i < steps; i++) {
        curr = parent[curr];
    }

    free(dist);
    free(parent);
    return curr;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Graph g1, g2;
    init_graph(&g1, n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(&g1, u, v);
    }

    init_graph(&g2, m);
    for (int i = 0; i < m - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(&g2, u, v);
    }

    int c1 = find_center(&g1);
    int c2 = find_center(&g2);

    printf("%d %d\n", c1, c2);

    free_graph(&g1);
    free_graph(&g2);

    return 0;
}
